        let delta = _mm256_sub_ps(q, vf);
        sum = _mm256_add_ps(sum, _mm256_mul_ps(delta, delta));
    }

    let lo = _mm256_castps256_ps128(sum);
    let hi = _mm256_extractf128_ps(sum, 1);
    let sum = _mm_add_ps(lo, hi);
    let sum = _mm_hadd_ps(sum, sum);
    let sum = _mm_hadd_ps(sum, sum);
    _mm_cvtss_f32(sum)
}

